-- Generated by Murakumo for duckdb: the project as plain SQL, without dbt.
-- An incremental model: built in full the first time, then only rows past the watermark.
CREATE TABLE IF NOT EXISTS intermediate.hub_customer AS
-- A Data Vault hub: insert-only. Each hub_customer_hk is added once, the first time it is loaded.

with customer as (

    select * from staging.stg_tpch_erp__customer

),

incoming as (

    select
        MD5(COALESCE(UPPER(TRIM(CAST(CAST(customer.c_custkey AS BIGINT) AS TEXT))), '')) as hub_customer_hk,
        cast(customer.c_custkey as BIGINT) as customer_number,
        cast(customer._ingested_at as TIMESTAMPTZ) as load_date,
        'tpch_erp' as record_source
    from customer

),

ranked as (

    select
        incoming.*,
        row_number() over (
            partition by incoming.hub_customer_hk
            order by incoming.load_date asc
        ) as row_in_batch
    from incoming

)

select
    ranked.hub_customer_hk,
    ranked.customer_number,
    ranked.load_date,
    ranked.record_source
from ranked

where ranked.row_in_batch = 1;
-- The rows past the watermark, kept aside while the old versions of them are removed.
DROP TABLE IF EXISTS hub_customer__new;
CREATE TEMPORARY TABLE hub_customer__new AS
-- A Data Vault hub: insert-only. Each hub_customer_hk is added once, the first time it is loaded.

with customer as (

    select * from staging.stg_tpch_erp__customer

),

incoming as (

    select
        MD5(COALESCE(UPPER(TRIM(CAST(CAST(customer.c_custkey AS BIGINT) AS TEXT))), '')) as hub_customer_hk,
        cast(customer.c_custkey as BIGINT) as customer_number,
        cast(customer._ingested_at as TIMESTAMPTZ) as load_date,
        'tpch_erp' as record_source
    from customer

    where cast(customer._ingested_at as TIMESTAMPTZ) > (select coalesce(max(load_date), cast('1900-01-01' as TIMESTAMPTZ)) from intermediate.hub_customer)

),

ranked as (

    select
        incoming.*,
        row_number() over (
            partition by incoming.hub_customer_hk
            order by incoming.load_date asc
        ) as row_in_batch
    from incoming

)
,

latest as (

    select hub_customer_hk
    from (
        select
            existing.hub_customer_hk,
            row_number() over (partition by existing.hub_customer_hk order by existing.load_date desc) as row_in_table
        from intermediate.hub_customer as existing
    ) as versions
    where row_in_table = 1

)

select
    ranked.hub_customer_hk,
    ranked.customer_number,
    ranked.load_date,
    ranked.record_source
from ranked

left join latest
    on latest.hub_customer_hk = ranked.hub_customer_hk

where ranked.row_in_batch = 1

    and latest.hub_customer_hk is null;
INSERT INTO intermediate.hub_customer (hub_customer_hk, customer_number, load_date, record_source)
SELECT hub_customer_hk, customer_number, load_date, record_source FROM hub_customer__new;
DROP TABLE hub_customer__new;
